<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title??'Tasks for Today') ?></title><link rel="stylesheet" href="<?= base_url('css/app.css') ?>"></head><body><header><a class="brand" href="<?= site_url('/') ?>">Tasks for Today</a><nav><a href="<?= site_url('/') ?>">Today</a><a href="<?= site_url('tasks') ?>">Task List</a><a href="<?= site_url('profile') ?>">Profile</a><a href="<?= site_url('about') ?>">About</a><?php if(session('is_logged_in')): ?><a href="<?= site_url('tasks/new') ?>">New Task</a><form action="<?= site_url('logout') ?>" method="post"><?= csrf_field() ?><button>Logout</button></form><?php else: ?><a href="<?= site_url('login') ?>">Login</a><?php endif; ?></nav></header><main><?php foreach(['success','error'] as $type): if(session()->getFlashdata($type)): ?><div class="alert <?= $type ?>"><?= esc(session()->getFlashdata($type)) ?></div><?php endif; endforeach; ?><?= $this->renderSection('content') ?></main></body></html>
